267:         if (node instanceof TableScan) {
268:             return Optional.of((TableScan) node);
269:         } else {
270:             if (FlinkHints.canTransposeToTableScan(node)) {
271:                 return getTableScan(node.getInput(0));
272:             } else {
273:                 return Optional.empty();
274:             }
275:         }
