307:                         if (!optionCheckedStatus.containsKey(table)) {
308:                             // all options are not checked when init
309:                             optionCheckedStatus.put(table, false);
310:                         }
311:                     });
312:         } else {
313:             allOptionsInJoinHints.put(
314:                     hintName,
315:                     new HashSet<>(definedTables)
316:                             .stream()
317:                                     // all options are not checked when init
318:                                     .collect(Collectors.toMap(table -> table, table -> false)));
319:         }
320:     }
