391:     private BufferBuilder toBufferBuilder(MemorySegment memorySegment, int targetChannel) {
392:         if (memorySegment == null) {
393:             return null;
394:         }
395: 
396:         if (targetChannel == UNKNOWN_CHANNEL) {
397:             return new BufferBuilder(memorySegment, this);
398:         } else {
399:             return new BufferBuilder(memorySegment, subpartitionBufferRecyclers[targetChannel]);
400:         }
401:     }
