60:     /** The ID of the job this graph has been built for. */
61:     private final JobID jobID;
62: 
63:     /** The name of the original job graph. */
64:     private final String jobName;
65: 
66:     /** All job vertices that are part of this graph. */
67:     private final Map<JobVertexID, ArchivedExecutionJobVertex> tasks;
68: 
69:     /** All vertices, in the order in which they were created. * */
70:     private final List<ArchivedExecutionJobVertex> verticesInCreationOrder;
71: 
72:     /**
73:      * Timestamps (in milliseconds as returned by {@code System.currentTimeMillis()} when the
74:      * execution graph transitioned into a certain state. The index into this array is the ordinal
75:      * of the enum value, i.e. the timestamp when the graph went into state "RUNNING" is at {@code
76:      * stateTimestamps[RUNNING.ordinal()]}.
77:      */
