98:     private final String jsonPlan;
99:     private final StringifiedAccumulatorResult[] archivedUserAccumulators;
100:     private final ArchivedExecutionConfig archivedExecutionConfig;
101:     private final boolean isStoppable;
102:     private final Map<String, SerializedValue<OptionalFailure<Object>>> serializedUserAccumulators;
