214:     @Override
215:     public Iterable<ArchivedExecutionJobVertex> getVerticesTopologically() {
216:         // we return a specific iterator that does not fail with concurrent modifications
217:         // the list is append only, so it is safe for that
218:         final int numElements = this.verticesInCreationOrder.size();
219: 
220:         return new Iterable<ArchivedExecutionJobVertex>() {
221:             @Override
222:             public Iterator<ArchivedExecutionJobVertex> iterator() {
223:                 return new Iterator<ArchivedExecutionJobVertex>() {
224:                     private int pos = 0;
225: 
226:                     @Override
227:                     public boolean hasNext() {
228:                         return pos < numElements;
229:                     }
230: 
231:                     @Override
232:                     public ArchivedExecutionJobVertex next() {
233:                         if (hasNext()) {
234:                             return verticesInCreationOrder.get(pos++);
235:                         } else {
236:                             throw new NoSuchElementException();
237:                         }
238:                     }
239: 
240:                     @Override
241:                     public void remove() {
242:                         throw new UnsupportedOperationException();
243:                     }
244:                 };
245:             }
246:         };
247:     }
