319:     /**
320:      * Create a {@link ArchivedExecutionGraph} from the given {@link ExecutionGraph}.
321:      *
322:      * @param executionGraph to create the ArchivedExecutionGraph from
323:      * @return ArchivedExecutionGraph created from the given ExecutionGraph
324:      */
325:     public static ArchivedExecutionGraph createFrom(ExecutionGraph executionGraph) {
326:         return createFrom(executionGraph, null);
327:     }
