674:     /**
675:      * Creates the parallelism store that should be used to build the {@link ExecutionGraph}, which
676:      * will respect the vertex parallelism of the passed {@link JobGraph} in all execution modes.
677:      *
678:      * @param jobGraph The job graph for execution.
679:      * @param executionMode The mode of scheduler execution.
680:      * @param defaultMaxParallelismFunc a function for computing a default max parallelism if none
681:      *     is specified on a given vertex
682:      * @return The parallelism store.
683:      */
684:     @VisibleForTesting
685:     static VertexParallelismStore computeVertexParallelismStoreForExecution(
686:             JobGraph jobGraph,
687:             SchedulerExecutionMode executionMode,
688:             Function<JobVertex, Integer> defaultMaxParallelismFunc) {
689:         if (executionMode == SchedulerExecutionMode.REACTIVE) {
690:             return computeReactiveModeVertexParallelismStore(
691:                     jobGraph.getVertices(), defaultMaxParallelismFunc, false);
692:         }
693:         return SchedulerBase.computeVertexParallelismStore(
