1612:         if (getState().getJobStatus().isGloballyTerminalState()) {
1613:             // Job has reached the terminal state, so we can return all slots to the ResourceManager
1614:             // to speed things up because we no longer need them. This optimization lets us skip
1615:             // waiting for the slot pool service to close.
