219:         public static Settings of(
220:                 Configuration configuration,
221:                 @Nullable JobCheckpointingSettings checkpointingConfiguration)
222:                 throws ConfigurationException {
223:             final SchedulerExecutionMode executionMode =
224:                     configuration.get(JobManagerOptions.SCHEDULER_MODE);
225:             Duration submissionResourceWaitTimeoutDefault =
226:                     JobManagerOptions.SCHEDULER_SUBMISSION_RESOURCE_WAIT_TIMEOUT.defaultValue();
227:             Duration submissionStabilizationTimeoutDefault =
228:                     JobManagerOptions.SCHEDULER_SUBMISSION_RESOURCE_STABILIZATION_TIMEOUT
229:                             .defaultValue();
230:             if (executionMode == SchedulerExecutionMode.REACTIVE) {
231:                 submissionResourceWaitTimeoutDefault = Duration.ofMillis(-1);
232:                 submissionStabilizationTimeoutDefault = Duration.ZERO;
233:             }
234: 
235:             final Duration executingCooldownTimeout =
236:                     configuration.get(
237:                             JobManagerOptions.SCHEDULER_EXECUTING_COOLDOWN_AFTER_RESCALING);
238: 
239:             final int rescaleOnFailedCheckpointsCount =
240:                     configuration.get(
241:                             JobManagerOptions.SCHEDULER_RESCALE_TRIGGER_MAX_CHECKPOINT_FAILURES);
242:             if (rescaleOnFailedCheckpointsCount < 1) {
243:                 throw new ConfigurationException(
244:                         String.format(
245:                                 "%s should have a value of 1 or higher.",
246:                                 JobManagerOptions.SCHEDULER_RESCALE_TRIGGER_MAX_CHECKPOINT_FAILURES
247:                                         .key()));
248:             }
249: 
250:             // default value generation is documented in JobManagerOption
251:             final Duration maximumDelayForRescaleTriggerDefault =
252:                     checkpointingConfiguration != null
253:                                     && checkpointingConfiguration
254:                                             .getCheckpointCoordinatorConfiguration()
255:                                             .isCheckpointingEnabled()
256:                             // incrementing the rescaleOnFailedCheckpointsCount by 1 is done to
257:                             // avoid introducing a race-condition between the two parameters
258:                             // (SCHEDULER_RESCALE_TRIGGER_MAX_CHECKPOINT_FAILURES and
259:                             // SCHEDULER_RESCALE_TRIGGER_MAX_DELAY). Without the increment, we would
260:                             // have two configuration parameters that result in roughly the same
261:                             // timeout (with the SCHEDULER_RESCALE_TRIGGER_MAX_DELAY being probably
262:                             // a bit faster). The user might experience unexpected behavior if the
263:                             // SCHEDULER_RESCALE_TRIGGER_MAX_CHECKPOINT_FAILURES is configured and
264:                             // SCHEDULER_RESCALE_TRIGGER_MAX_DELAY is kept untouched in that case.
265:                             // Incrementing the default value should help avoiding causing this kind
266:                             // of confusing race condition.
267:                             ? Duration.ofMillis(
268:                                     (rescaleOnFailedCheckpointsCount + 1)
269:                                             * checkpointingConfiguration
270:                                                     .getCheckpointCoordinatorConfiguration()
271:                                                     .getCheckpointInterval())
272:                             : Duration.ZERO;
273: 
274:             if (configuration.getOptional(JobManagerOptions.MIN_PARALLELISM_INCREASE).isPresent()) {
275:                 LOG.warn(
276:                         "The configuration option {} is deprecated and will be removed in future versions. It's not used anymore. "
277:                                 + "Please use the configuration option {} and {} to control the sensitivity of a scaling operation. "
278:                                 + "Or you can change resource requirements of a running job can using the REST API.",
279:                         JobManagerOptions.MIN_PARALLELISM_INCREASE.key(),
280:                         JobManagerOptions.SCHEDULER_EXECUTING_COOLDOWN_AFTER_RESCALING.key(),
281:                         JobManagerOptions.SCHEDULER_EXECUTING_RESOURCE_STABILIZATION_TIMEOUT.key());
282:             }
283: 
284:             return new Settings(
285:                     executionMode,
286:                     configuration
287:                             .getOptional(
288:                                     JobManagerOptions.SCHEDULER_SUBMISSION_RESOURCE_WAIT_TIMEOUT)
289:                             .orElse(submissionResourceWaitTimeoutDefault),
290:                     configuration
291:                             .getOptional(
292:                                     JobManagerOptions
293:                                             .SCHEDULER_SUBMISSION_RESOURCE_STABILIZATION_TIMEOUT)
294:                             .orElse(submissionStabilizationTimeoutDefault),
295:                     configuration.get(JobManagerOptions.SLOT_IDLE_TIMEOUT),
296:                     executingCooldownTimeout,
297:                     configuration.get(
298:                             JobManagerOptions.SCHEDULER_EXECUTING_RESOURCE_STABILIZATION_TIMEOUT),
299:                     configuration.get(
300:                             SCHEDULER_RESCALE_TRIGGER_MAX_DELAY,
301:                             maximumDelayForRescaleTriggerDefault),
302:                     rescaleOnFailedCheckpointsCount);
303:         }
