1098:     @VisibleForTesting
1099:     static boolean hasDesiredResources(
1100:             ResourceCounter desiredResources, Collection<? extends SlotInfo> freeSlots) {
1101:         ResourceCounter outstandingResources = desiredResources;
1102:         final Iterator<? extends SlotInfo> slotIterator = freeSlots.iterator();
1103: 
1104:         while (!outstandingResources.isEmpty() && slotIterator.hasNext()) {
1105:             final SlotInfo slotInfo = slotIterator.next();
1106:             final ResourceProfile resourceProfile = slotInfo.getResourceProfile();
1107: 
1108:             if (outstandingResources.containsResource(resourceProfile)) {
1109:                 outstandingResources = outstandingResources.subtract(resourceProfile, 1);
1110:             } else {
1111:                 outstandingResources = outstandingResources.subtract(ResourceProfile.UNKNOWN, 1);
1112:             }
1113:         }
1114: 
1115:         return outstandingResources.isEmpty();
1116:     }
