1402:     @Nonnull
1403:     private ExecutionGraph assignSlotsToExecutionGraph(
1404:             ExecutionGraph executionGraph, ReservedSlots reservedSlots) {
1405:         for (ExecutionVertex executionVertex : executionGraph.getAllExecutionVertices()) {
1406:             final LogicalSlot assignedSlot = reservedSlots.getSlotFor(executionVertex.getID());
1407:             final CompletableFuture<Void> registrationFuture =
1408:                     executionVertex
1409:                             .getCurrentExecutionAttempt()
1410:                             .registerProducedPartitions(assignedSlot.getTaskManagerLocation());
1411:             Preconditions.checkState(
1412:                     registrationFuture.isDone(),
1413:                     "Partition registration must be completed immediately for reactive mode");
1414: 
1415:             executionVertex.tryAssignResource(assignedSlot);
1416:         }
1417: 
1418:         return executionGraph;
1419:     }
