1421:     private CompletableFuture<ExecutionGraph> createExecutionGraphAndRestoreStateAsync(
1422:             VertexParallelismStore adjustedParallelismStore) {
1423:         backgroundTask.abort();
1424: 
1425:         backgroundTask =
1426:                 backgroundTask.runAfter(
1427:                         () -> createExecutionGraphAndRestoreState(adjustedParallelismStore),
1428:                         ioExecutor);
1429: 
1430:         return FutureUtils.switchExecutor(
1431:                 backgroundTask.getResultFuture(), getMainThreadExecutor());
1432:     }
