1440:                 checkpointsCleaner,
1441:                 checkpointIdCounter,
1442:                 checkpointStatsTracker,
1443:                 TaskDeploymentDescriptorFactory.PartitionLocationConstraint.MUST_BE_KNOWN,
1444:                 initializationTimestamp,
1445:                 vertexAttemptNumberStore,
1446:                 adjustedParallelismStore,
1447:                 deploymentTimeMetrics,
1448:                 // adaptive scheduler works in streaming mode, actually it only
1449:                 // supports must be pipelined result partition, mark partition finish is
