1479:     @Override
1480:     public FailureResult howToHandleFailure(
1481:             Throwable failure, CompletableFuture<Map<String, String>> failureLabels) {
1482:         FailureResult failureResult = howToHandleFailure(failure);
1483:         if (reportEventsAsSpans) {
1484:             // TODO: replace with reporting as event once events are supported.
1485:             // Add reporting as callback for when the failure labeling is completed.
1486:             failureLabels.thenAcceptAsync(
