578:     private static void assertPreconditions(JobGraph jobGraph) throws RuntimeException {
579:         Preconditions.checkState(
580:                 jobGraph.getJobType() == JobType.STREAMING,
581:                 "The adaptive scheduler only supports streaming jobs.");
582: 
583:         for (JobVertex vertex : jobGraph.getVertices()) {
584:             Preconditions.checkState(
585:                     vertex.getParallelism() > 0,
586:                     "The adaptive scheduler expects the parallelism being set for each JobVertex (violated JobVertex: %s).",
587:                     vertex.getID());
588:             for (JobEdge jobEdge : vertex.getInputs()) {
589:                 Preconditions.checkState(
590:                         jobEdge.getSource()
591:                                 .getResultType()
592:                                 .isPipelinedOrPipelinedBoundedResultPartition(),
593:                         "The adaptive scheduler supports pipelined data exchanges (violated by %s -> %s).",
594:                         jobEdge.getSource().getProducer(),
595:                         jobEdge.getTarget().getID());
596:             }
597:         }
598:     }
