600:     /**
601:      * Creates the parallelism store for a set of vertices, optionally with a flag to leave the
602:      * vertex parallelism unchanged. If the flag is set, the parallelisms must be valid for
603:      * execution.
604:      *
605:      * <p>We need to set parallelism to the max possible value when requesting resources, but when
606:      * executing the graph we should respect what we are actually given.
607:      *
608:      * @param vertices The vertices to store parallelism information for
609:      * @param adjustParallelism Whether to adjust the parallelism
610:      * @param defaultMaxParallelismFunc a function for computing a default max parallelism if none
611:      *     is specified on a given vertex
612:      * @return The parallelism store.
613:      */
614:     @VisibleForTesting
615:     static VertexParallelismStore computeReactiveModeVertexParallelismStore(
616:             Iterable<JobVertex> vertices,
617:             Function<JobVertex, Integer> defaultMaxParallelismFunc,
618:             boolean adjustParallelism) {
619:         DefaultVertexParallelismStore store = new DefaultVertexParallelismStore();
620: 
621:         for (JobVertex vertex : vertices) {
622:             // if no max parallelism was configured by the user, we calculate and set a default
623:             final int maxParallelism =
624:                     vertex.getMaxParallelism() == JobVertex.MAX_PARALLELISM_DEFAULT
625:                             ? defaultMaxParallelismFunc.apply(vertex)
626:                             : vertex.getMaxParallelism();
627:             // If the parallelism has already been adjusted, respect what has been configured in the
628:             // vertex. Otherwise, scale it to the max parallelism to attempt to be "as parallel as
629:             // possible"
630:             final int parallelism;
631:             if (adjustParallelism) {
632:                 parallelism = maxParallelism;
633:             } else {
634:                 parallelism = vertex.getParallelism();
635:             }
636: 
637:             VertexParallelismInformation parallelismInfo =
638:                     new DefaultVertexParallelismInfo(
639:                             parallelism,
640:                             maxParallelism,
641:                             // Allow rescaling if the new desired max parallelism
642:                             // is not less than what was declared here during scheduling.
643:                             // This prevents the situation where more resources are requested
644:                             // based on the computed default, when actually fewer are necessary.
645:                             (newMax) ->
646:                                     newMax >= maxParallelism
647:                                             ? Optional.empty()
648:                                             : Optional.of(
649:                                                     "Cannot lower max parallelism in Reactive mode."));
650:             store.setParallelismInfo(vertex.getID(), parallelismInfo);
651:         }
652: 
653:         return store;
654:     }
655: 
656:     /**
657:      * Creates the parallelism store that should be used for determining scheduling requirements,
658:      * which may choose different parallelisms than set in the {@link JobGraph} depending on the
659:      * execution mode.
660:      *
661:      * @param jobGraph The job graph for execution.
662:      * @param executionMode The mode of scheduler execution.
663:      * @return The parallelism store.
664:      */
665:     private static VertexParallelismStore computeVertexParallelismStore(
666:             JobGraph jobGraph, SchedulerExecutionMode executionMode) {
667:         if (executionMode == SchedulerExecutionMode.REACTIVE) {
668:             return computeReactiveModeVertexParallelismStore(
669:                     jobGraph.getVertices(), SchedulerBase::getDefaultMaxParallelism, true);
670:         }
671:         return SchedulerBase.computeVertexParallelismStore(jobGraph);
672:     }
673: 
674:     /**
675:      * Creates the parallelism store that should be used to build the {@link ExecutionGraph}, which
676:      * will respect the vertex parallelism of the passed {@link JobGraph} in all execution modes.
677:      *
678:      * @param jobGraph The job graph for execution.
679:      * @param executionMode The mode of scheduler execution.
680:      * @param defaultMaxParallelismFunc a function for computing a default max parallelism if none
681:      *     is specified on a given vertex
682:      * @return The parallelism store.
683:      */
684:     @VisibleForTesting
685:     static VertexParallelismStore computeVertexParallelismStoreForExecution(
686:             JobGraph jobGraph,
687:             SchedulerExecutionMode executionMode,
688:             Function<JobVertex, Integer> defaultMaxParallelismFunc) {
689:         if (executionMode == SchedulerExecutionMode.REACTIVE) {
690:             return computeReactiveModeVertexParallelismStore(
691:                     jobGraph.getVertices(), defaultMaxParallelismFunc, false);
692:         }
693:         return SchedulerBase.computeVertexParallelismStore(
694:                 jobGraph.getVertices(), defaultMaxParallelismFunc);
695:     }
