171: 
172:         final String queryName = "hakuna-matata";
173: 
174:         source.keyBy(
175:                         new KeySelector<Tuple2<Integer, Long>, Integer>() {
176:                             private static final long serialVersionUID = 7143749578983540352L;
177: 
178:                             @Override
179:                             public Integer getKey(Tuple2<Integer, Long> value) {
180:                                 return value.f0;
181:                             }
182:                         })
183:                 .asQueryableState(queryName, reducingState);
184: 
185:         try (AutoCancellableJob autoCancellableJob =
186:                 new AutoCancellableJob(deadline, clusterClient, env)) {
187: 
188:             final JobID jobId = autoCancellableJob.getJobId();
189:             final JobGraph jobGraph = autoCancellableJob.getJobGraph();
190: 
191:             clusterClient.submitJob(jobGraph).get();
192: 
193:             final AtomicLongArray counts = new AtomicLongArray(numKeys);
194: 
195:             final List<CompletableFuture<ReducingState<Tuple2<Integer, Long>>>> futures =
196:                     new ArrayList<>(numKeys);
197: 
198:             boolean allNonZero = false;
199:             while (!allNonZero && deadline.hasTimeLeft()) {
200:                 allNonZero = true;
201:                 futures.clear();
202: 
203:                 for (int i = 0; i < numKeys; i++) {
204:                     final int key = i;
205: 
206:                     if (counts.get(key) > 0L) {
207:                         // Skip this one
208:                         continue;
209:                     } else {
210:                         allNonZero = false;
211:                     }
212: 
213:                     CompletableFuture<ReducingState<Tuple2<Integer, Long>>> result =
214:                             getKvState(
215:                                     deadline,
216:                                     client,
217:                                     jobId,
