236:                             });
237: 
238:                     futures.add(result);
239:                 }
240: 
241:                 // wait for all the futures to complete
242:                 CompletableFuture.allOf(futures.toArray(new CompletableFuture<?>[futures.size()]))
243:                         .get(deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS);
244:             }
245: 
246:             assertThat(allNonZero).isTrue().withFailMessage("Not all keys are non-zero");
247: 
248:             // All should be non-zero
249:             for (int i = 0; i < numKeys; i++) {
250:                 long count = counts.get(i);
251:                 assertThat(count)
252:                         .isGreaterThan(0)
253:                         .withFailMessage("Count at position " + i + " is " + count);
254:             }
255:         }
256:     }
