1409:     /**
1410:      * Retry a query for state for keys between 0 and {@link #maxParallelism} until
1411:      * <tt>expected</tt> equals the value of the result tuple's second field.
1412:      */
1413:     private void executeValueQuery(
1414:             final Deadline deadline,
1415:             final QueryableStateClient client,
1416:             final JobID jobId,
1417:             final String queryableStateName,
1418:             final ValueStateDescriptor<Tuple2<Integer, Long>> stateDescriptor,
1419:             final long expected)
1420:             throws Exception {
1421: 
1422:         for (int key = 0; key < maxParallelism; key++) {
1423:             boolean success = false;
1424:             while (deadline.hasTimeLeft() && !success) {
1425:                 CompletableFuture<ValueState<Tuple2<Integer, Long>>> future =
1426:                         getKvState(
1427:                                 deadline,
1428:                                 client,
1429:                                 jobId,
1430:                                 queryableStateName,
1431:                                 key,
1432:                                 BasicTypeInfo.INT_TYPE_INFO,
1433:                                 stateDescriptor,
1434:                                 false,
1435:                                 executor);
1436: 
1437:                 Tuple2<Integer, Long> value =
1438:                         future.get(deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS).value();
1439: 
1440:                 assertThat(key).isEqualTo(value.f0.intValue()).withFailMessage("Key mismatch");
1441:                 if (expected == value.f1) {
1442:                     success = true;
1443:                 } else {
1444:                     // Retry
1445:                     Thread.sleep(RETRY_TIMEOUT);
1446:                 }
1447:             }
1448: 
1449:             assertThat(success).isTrue().withFailMessage("Did not succeed query");
1450:         }
1451:     }
