147:     /**
148:      * Runs a simple topology producing random (key, 1) pairs at the sources (where number of keys
149:      * is in fixed in range 0...numKeys). The records are keyed and a reducing queryable state
150:      * instance is created, which sums up the records.
151:      *
152:      * <p>After submitting the job in detached mode, the QueryableStateCLient is used to query the
153:      * counts of each key in rounds until all keys have non-zero counts.
154:      */
155:     @Test
156:     void testQueryableState() throws Exception {
157:         final Deadline deadline = Deadline.now().plus(TEST_TIMEOUT);
158:         final int numKeys = 256;
159: 
160:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
161:         env.setStateBackend(stateBackend);
162:         env.setParallelism(maxParallelism);
163:         // Very important, because cluster is shared between tests and we
164:         // don't explicitly check that all slots are available before
165:         // submitting.
166:         RestartStrategyUtils.configureFixedDelayRestartStrategy(env, Integer.MAX_VALUE, 1000L);
167:         DataStream<Tuple2<Integer, Long>> source = env.addSource(new TestKeyRangeSource(numKeys));
168: 
169:         ReducingStateDescriptor<Tuple2<Integer, Long>> reducingState =
170:                 new ReducingStateDescriptor<>("any-name", new SumReduce(), source.getType());
171: 
172:         final String queryName = "hakuna-matata";
173: 
174:         source.keyBy(
175:                         new KeySelector<Tuple2<Integer, Long>, Integer>() {
176:                             private static final long serialVersionUID = 7143749578983540352L;
177: 
178:                             @Override
179:                             public Integer getKey(Tuple2<Integer, Long> value) {
180:                                 return value.f0;
181:                             }
182:                         })
183:                 .asQueryableState(queryName, reducingState);
184: 
185:         try (AutoCancellableJob autoCancellableJob =
186:                 new AutoCancellableJob(deadline, clusterClient, env)) {
187: 
188:             final JobID jobId = autoCancellableJob.getJobId();
189:             final JobGraph jobGraph = autoCancellableJob.getJobGraph();
190: 
191:             clusterClient.submitJob(jobGraph).get();
192: 
193:             final AtomicLongArray counts = new AtomicLongArray(numKeys);
194: 
195:             final List<CompletableFuture<ReducingState<Tuple2<Integer, Long>>>> futures =
196:                     new ArrayList<>(numKeys);
197: 
198:             boolean allNonZero = false;
199:             while (!allNonZero && deadline.hasTimeLeft()) {
200:                 allNonZero = true;
201:                 futures.clear();
202: 
203:                 for (int i = 0; i < numKeys; i++) {
204:                     final int key = i;
205: 
206:                     if (counts.get(key) > 0L) {
207:                         // Skip this one
208:                         continue;
209:                     } else {
210:                         allNonZero = false;
211:                     }
212: 
213:                     CompletableFuture<ReducingState<Tuple2<Integer, Long>>> result =
214:                             getKvState(
215:                                     deadline,
216:                                     client,
217:                                     jobId,
218:                                     queryName,
219:                                     key,
220:                                     BasicTypeInfo.INT_TYPE_INFO,
221:                                     reducingState,
222:                                     false,
223:                                     executor);
224: 
225:                     result.thenAccept(
226:                             response -> {
227:                                 assertThatCode(
228:                                                 () -> {
229:                                                     Tuple2<Integer, Long> res = response.get();
230:                                                     counts.set(key, res.f1);
231:                                                     assertThat(key)
232:                                                             .isEqualTo(res.f0.intValue())
233:                                                             .withFailMessage("Key mismatch");
234:                                                 })
235:                                         .doesNotThrowAnyException();
236:                             });
237: 
238:                     futures.add(result);
239:                 }
240: 
241:                 // wait for all the futures to complete
242:                 CompletableFuture.allOf(futures.toArray(new CompletableFuture<?>[futures.size()]))
243:                         .get(deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS);
244:             }
245: 
246:             assertThat(allNonZero).isTrue().withFailMessage("Not all keys are non-zero");
247: 
248:             // All should be non-zero
249:             for (int i = 0; i < numKeys; i++) {
250:                 long count = counts.get(i);
251:                 assertThat(count)
252:                         .isGreaterThan(0)
253:                         .withFailMessage("Count at position " + i + " is " + count);
254:             }
255:         }
256:     }
