1288:     private static class AutoCancellableJob implements AutoCloseable {
1289: 
1290:         private final ClusterClient<?> clusterClient;
1291:         private final JobGraph jobGraph;
1292: 
1293:         private final JobID jobId;
1294: 
1295:         private final Deadline deadline;
1296: 
1297:         AutoCancellableJob(
1298:                 Deadline deadline,
1299:                 final ClusterClient<?> clusterClient,
1300:                 final StreamExecutionEnvironment env) {
1301:             Preconditions.checkNotNull(env);
1302: 
1303:             this.clusterClient = Preconditions.checkNotNull(clusterClient);
1304:             this.jobGraph = env.getStreamGraph().getJobGraph();
1305: 
1306:             this.jobId = Preconditions.checkNotNull(jobGraph.getJobID());
1307: 
1308:             this.deadline = deadline;
1309:         }
1310: 
1311:         JobGraph getJobGraph() {
1312:             return jobGraph;
1313:         }
1314: 
1315:         JobID getJobId() {
1316:             return jobId;
1317:         }
1318: 
1319:         @Override
1320:         public void close() throws Exception {
1321:             // Free cluster resources
1322:             clusterClient.cancel(jobId).get();
1323:             // cancel() is non-blocking so do this to make sure the job finished
1324:             CompletableFuture<JobStatus> jobStatusFuture =
1325:                     FutureUtils.retrySuccessfulWithDelay(
1326:                             () -> clusterClient.getJobStatus(jobId),
1327:                             Duration.ofMillis(50),
1328:                             deadline,
1329:                             (jobStatus) -> jobStatus.equals(JobStatus.CANCELED),
1330:                             new ScheduledExecutorServiceAdapter(EXECUTOR_EXTENSION.getExecutor()));
1331:             assertThat(jobStatusFuture.get(deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS))
1332:                     .isEqualTo(JobStatus.CANCELED);
