1362:     private static <K, S extends State, V> void getKvStateIgnoringCertainExceptions(
1363:             final Deadline deadline,
1364:             final CompletableFuture<S> resultFuture,
1365:             final QueryableStateClient client,
1366:             final JobID jobId,
1367:             final String queryName,
1368:             final K key,
1369:             final TypeInformation<K> keyTypeInfo,
1370:             final StateDescriptor<S, V> stateDescriptor,
1371:             final boolean failForUnknownKeyOrNamespace,
1372:             final ScheduledExecutor executor) {
1373: 
